import hashlib, json
from pathlib import Path
root = Path('products/services/sqlite-repair/launch')
paths = ('launch-baseline.json', 'pre-cutoff-live-2026-11-21.html', 'window-verdict.json')
report = {'scope': 'Committed local evidence for the SQLite verdict due 2026-11-22T00:00:00Z. File presence and hashes establish neither publication recency nor demand.', 'files': {}}
for name in paths:
    path = root / name
    if path.is_file():
        data = path.read_bytes()
        report['files'][name] = {'path': str(path), 'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
    else:
        report['files'][name] = {'state': 'ABSENT_FROM_SELECTED_INPUT'}
report['feedback_snapshot'] = {'observed_private_cycle_utc': '2026-11-21T10:05:20.153220+00:00', 'classified_requests_across_all_reported_sources': 0, 'unclassified_sources': 5, 'excluded_sources': 5, 'attributable_sqlite_demand': 'UNKNOWN', 'source': 'Host commercial_feedback and private-mail cycle metadata supplied with the decision snapshot. Refresh at cutoff.'}
root.mkdir(parents=True, exist_ok=True)
output = root / 'cutoff-evidence-inputs-2026-11-21.json'
output.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
